"""Independent draft/checkpoint/archive reader; no metadata compiler or test invocation."""
from pathlib import Path
import json,hashlib,zipfile
from native_E149_recovery_contract import R,FORMAL,read,sha,encoded,require,check_pins
def main():
 w=read(R/'工作佇列.json');ref=w['current_E149_hide97_venom98_draft_development'];ep=Path(ref['evidence']);require(sha(ep)==ref['evidence_sha256'],'draft evidence changed');e=read(ep);check_pins(e['source_pins']);check_pins(e['normal_product_pins']);inputs=read(e['base_compiled_inputs']);require(len(inputs)==1049,'normal count differs');check_pins({str(R/n):h for n,h in inputs.items()});require(w['current_E149_selector80_development']==e['previous_qualified_metadata'] and sha(w['current_formal_reference_identity']['formal'])==FORMAL,'base metadata/formal changed');require(e['metadata_compilers_started']==e['tests_executed']==e['desktop_inputs']==0 and not any(e[k]for k in ['tests_compiled','PEs_linked','outputs_executed','production_applied','canonical_registry_selected','whole_goal_complete']),'scope differs')
 k=read(e['draft']);require(sha(e['draft'])==e['draft_sha256'] and k['hide97_static_frame_zero_and_retirement_unresolved'] and k['hide97_2941_no_pixels_assumption_rejected'] and k['server_material_timeline_review_pending'] and (k['new_draft_QA_cases'],k['new_draft_resource_opt_in_cases'],e['previous_metadata_cases'])==(4,1,455),'draft scope differs');cases=ignored=0
 for name,row in k['runtime_overrides'].items():
  require(sha(row['predecessor'])==row['predecessor_sha256'],'prior source differs');s=Path(row['predecessor']).read_text('utf-8-sig')
  for a,b in row['changes']:require(s.count(a)==1,'ambiguous delta');s=s.replace(a,b)
  for p in row['supplements']:
   require(sha(p['path'])==p['sha256'],'supplement differs');extra=Path(p['path']).read_text('utf-8-sig');s+='\n'+extra;cases+=extra.count('#[test]');ignored+=extra.count('#[ignore=')
  require(s==Path(row['path']).read_text('utf-8-sig') and sha(row['path'])==row['sha256'],'draft reconstruction differs')
 require((len(k['runtime_overrides']),cases,ignored,len(k['effective_overlay_files']))==(4,4,1,42),'draft inventory differs');require(sha(e['raw_archive'])==e['raw_archive_sha256'],'raw changed')
 with zipfile.ZipFile(e['raw_archive'])as z:require(len(z.namelist())==len(e['raw_archive_files']) and all(hashlib.sha256(z.read(Path(p).relative_to(R).as_posix())).hexdigest().upper()==h for p,h in e['raw_archive_files'].items()),'raw members differ')
 rb=read(ep.with_name('readback.json'));require(rb['evidence_sha256']==sha(ep) and len(rb['after_files'])==8 and all(sha(R/n)==h for n,h in rb['after_files'].items()),'checkpoint differs')
 with zipfile.ZipFile(ep.with_name('before.zip'))as z:require(all(hashlib.sha256(z.read(n)).hexdigest().upper()==h for n,h in rb['before_files'].items()),'before members differ')
 master=R/'驗證紀錄/current/master-report-current-work/20261024-190121-344716/readback.json';m=read(master);report=R.parent/'LiTo381-總開發報告.md';require(sha(report)==m['after_sha256'] and report.read_bytes()==master.with_name('after.md').read_bytes() and m['latest_draft_evidence']==str(ep),'master differs');text=report.read_text('utf-8-sig');require(all(v in text for v in ['未編譯草稿','455','86／剩94','0x460','無action不等於無像素','測試與桌面操作暫緩']),'master scope absent');require(w['current_user_requested_goal']['test_execution_deferred_by_user'] and w['current_user_requested_goal']['desktop_automation_deferred_by_user'] and not w['active_workloads'] and not w['active_workload_sessions'] and not w['source_and_corresponding_QA_frozen'],'phase differs');require(e['current_fixture_binding_unchanged']==w['current_E149_fixture_binding'] and e['current_formal_suite_unchanged']==w['current_E149_recovery_suite_development'] and e['canonical_registry_unchanged']==w['current_isolated_development']['candidates'],'G06/registry differs')
 result=dict(evidence=str(ep),evidence_sha256=sha(ep),reader=str(Path(__file__).resolve()),reader_sha256=sha(Path(__file__).resolve()),draft_runtime_files=4,new_draft_QA_cases=4,metadata_compilers_started=0,tests_compiled=False,tests_executed=0,normal_inputs_checked=1049,eight_checkpoints_checked=8,normal_products_registry_formal_G06_unchanged=True,qualified_request_source_count_unchanged=86,qualified_missing_request_count_unchanged=94,master_report_sha256=sha(report),whole_goal_complete=False);ep.with_name('final-readback.json').write_bytes(encoded(result));print(json.dumps(result,ensure_ascii=False))
if __name__=='__main__':main()
